def Relu(Z):
    return numpy.maximum(0, Z)

def softmax(Z):
    A = numpy.exp(Z) / sum(numpy.exp(Z))
    return A

def forward_prop(W1, b1, W2, b2, X):
    Z1 = W1.dot(X) + b1
    A1 = Relu(Z1)
    Z2 = W2.dot(A1) + b2
    A2 = softmax(Z2)
    return (Z1, A1, Z2, A2)

def one_hot(Y):
    one_hot_Y = numpy.zeros((Y.size, Y.max() + 1))
    one_hot_Y[np.arange(Y.size), Y] = 1
    one_hot_Y = one_hot_Y.T
    return one_hot_Y

def deriv_Relu(Z):
    return Z > 0

def back_prop(Z1, A1, Z2, A2, W2, X, Y):
    int = Y.size
    one_hot_Y = one_hot(Y)
    dZ2 = A2 - one_hot_Y
    dW2 = 1 / int * dZ2.dot(A1.T)
    db2 = 1 / int * numpy.sum(dZ2)
    dZ1 = W2.T.dot(dZ2) * deriv_Relu(Z1)
    dW1 = 1 / int * dZ1.dot(X.T)
    db1 = 1 / int * numpy.sum(dZ1)
    return (dW1, db1, dW2, db2)

