import numpy
import pandas
import os
for dirname, str, filenames in os.walk('/kaggle/input'):
    for filename in filenames:
        print(os.path.join(dirname, filename))

def relu(x):
    return numpy.maximum(0, x)

def relu_backward(dout, x):
    dx = dout.copy()
    dx[x <= 0] = 0
    return dx

def softmax(x):
    e = numpy.exp(x - numpy.max(x))
    return e / numpy.sum(e)

def cross_entropy_loss(pred, label):
    loss = -numpy.log(pred[label] + 1e-12)
    d_out = pred.copy()
    d_out[label] -= 1
    return (loss, d_out)

