def relu(x):
    return np.maximum(0, x)

def relu_backward(dout, x):
    dx = dout.copy()
    dx[x <= 0] = 0
    return dx

def softmax(x):
    e = np.exp(x - np.max(x))
    return e / np.sum(e)

def cross_entropy_loss(pred, label):
    loss = -np.log(pred[label] + 1e-12)
    d_out = pred.copy()
    d_out[label] -= 1
    return loss, d_out

