def conv2d(img, kernel):
    k = kernel.shape[0]
    out_dim = img.shape[0] - k + 1
    out = numpy.zeros((out_dim, out_dim))
    for i in range(out_dim):
        for j in range(out_dim):
            out[i, j] = numpy.sum(img[i:i + k, j:j + k] * kernel)
    return out

