def train_and_evaluate_models(x_train, y_train, x_val, y_val):
    models = {'SVM': sklearn.svm.SVC(kernel='rbf', C=10, gamma='scale', random_state=42), 'KNN': sklearn.neighbors.KNeighborsClassifier(n_neighbors=3), 'Random Forest': sklearn.ensemble.RandomForestClassifier(n_estimators=100, random_state=42), 'Logistic Regression': sklearn.linear_model.LogisticRegression(max_iter=1000, random_state=42)}
    results = {}
    for name, model in models.items():
        print(f'\nTraining {name}...')
        start_time = time.time()
        model.fit(x_train, y_train)
        y_pred = model.predict(x_val)
        accuracy = sklearn.metrics.accuracy_score(y_val, y_pred)
        train_time = time.time() - start_time
        results[name] = {'model': model, 'accuracy': accuracy, 'train_time': train_time, 'predictions': y_pred}
        print(f'{name} Accuracy: {accuracy:.4f}')
        print(f'{name} Training Time: {train_time:.2f} seconds')
    return results

