        self.labels = labels
        self.transform = transform

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        # Reshape to 28x28, keep as uint8 for PIL transformations
        image = self.data[idx].reshape(28, 28).astype(np.uint8)

        if self.transform:
            # Apply augmentations (which includes ToTensor and normalization)
            image = self.transform(image)
        else:
            # For validation/test set: just normalize and convert to tensor
            image = torch.tensor(image / 255.0, dtype=torch.float32).unsqueeze(0)

        if self.labels is not None:
            label = torch.tensor(self.labels[idx], dtype=torch.long)
            return image, label
        else:
            return image

