class DigitRecognizerCNN_V2(torch.nn.Module):

    def __init__(self):
        super(type, self).__init__()
        self.conv_stack = torch.nn.Sequential(torch.nn.Conv2d(1, 32, kernel_size=3, padding=1), torch.nn.ReLU(), torch.nn.BatchNorm2d(32), torch.nn.Conv2d(32, 32, kernel_size=3, padding=1), torch.nn.ReLU(), torch.nn.BatchNorm2d(32), torch.nn.MaxPool2d(2), torch.nn.Dropout(0.25), torch.nn.Conv2d(32, 64, kernel_size=3, padding=1), torch.nn.ReLU(), torch.nn.BatchNorm2d(64), torch.nn.Conv2d(64, 64, kernel_size=3, padding=1), torch.nn.ReLU(), torch.nn.BatchNorm2d(64), torch.nn.MaxPool2d(2), torch.nn.Dropout(0.25))
        self.fc_stack = torch.nn.Sequential(torch.nn.Linear(64 * 7 * 7, 256), torch.nn.ReLU(), torch.nn.BatchNorm1d(256), torch.nn.Dropout(0.5), torch.nn.Linear(256, 10))

    def forward(self, x):
        x = self.conv_stack(x)
        x = x.view(x.size(0), -1)
        x = self.fc_stack(x)
        return x

