class ResidualUnit(tensorflow.keras.layers.Layer):

    def __init__(self, filters, strides=1, activation=tensorflow.keras.activations.relu, **kwargs):
        super().__init__(**kwargs)
        self.filters = filters
        self.strides = strides
        self.activation = activation
        self.main_layer = [tensorflow.keras.layers.Conv2D(filters, 3, strides=strides, padding='same', use_bias=False), tensorflow.keras.layers.BatchNormalization(), tensorflow.keras.layers.Activation('relu'), tensorflow.keras.layers.Conv2D(filters, 3, strides=1, padding='same', use_bias=False), tensorflow.keras.layers.BatchNormalization()]
        self.skip_layers = []
        if strides > 1:
            self.skip_layers = [tensorflow.keras.layers.Conv2D(filters, 1, strides=strides, padding='same', use_bias=False), tensorflow.keras.layers.BatchNormalization()]

    def call(self, inputs):
        Z = inputs
        for layer in self.main_layer:
            Z = layer(Z)
        skip_Z = inputs
        for layer in self.skip_layers:
            skip_Z = layer(skip_Z)
        return self.activation(Z + skip_Z)

