class ResidualUnit(keras.layers.Layer):
    def __init__(self, filters, strides = 1, activation = keras.activations.relu, **kwargs):
        super().__init__(**kwargs)
        self.filters = filters
        self.strides = strides
        self.activation = activation
        self.main_layer = [
            keras.layers.Conv2D(filters, 3, strides = strides, padding = "same", use_bias = False),
            keras.layers.BatchNormalization(),
            keras.layers.Activation("relu"),
            keras.layers.Conv2D(filters, 3, strides = 1, padding = "same", use_bias = False),
            keras.layers.BatchNormalization()
        ]
        self.skip_layers = []
        if strides > 1:
            self.skip_layers = [
                keras.layers.Conv2D(filters, 1, strides = strides, padding = "same", use_bias = False),
                keras.layers.BatchNormalization(),
            ]

    def call(self, inputs):
        # Forward pass through main path
        Z = inputs
        for layer in self.main_layer:
            Z = layer(Z)

        # Forward pass through skip path (identity if strides=1)
        skip_Z = inputs
        for layer in self.skip_layers:
            skip_Z = layer(skip_Z)

        # Add main path and skip path (Residual connection)
        return self.activation(Z + skip_Z)

